using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using AlpineQuestPort;
class RouteTests {
 static void Check(bool b,string text){if(!b)throw new Exception(text);Console.WriteLine("PASS "+text);}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var t=new Track{Name="Поворот"};t.Points.Add(new GeoPoint(0,0));t.Points.Add(new GeoPoint(0,.01));t.Points.Add(new GeoPoint(.01,.01));var p=RouteTerrain.Create(t);Check(p.Length>GeoMath.DistanceMeters(t.Points[0],t.Points[2])*1.3,"route follows bend rather than endpoint chord");Check(p.Points.Take(p.Points.Length/2).All(v=>Math.Abs(v.Lat)<1e-6),"first segment stays on route");Check(p.X.Zip(p.X.Skip(1),(a,b)=>b>a).All(v=>v),"distances strictly increase");Check(p.Heights.All(double.IsNaN),"missing DEM remains unknown");p.Heights[0]=100;p.Heights[1]=120;p.Heights[2]=110;var axes=ProfileAxes.Create(90,130,p.Heights,1100,650,0,false);var point=ProfilePointActions.At(p,axes,new Point((int)axes.Plot.Left,(int)axes.Plot.Top+10));Check(point!=null&&point.Elevation==100&&Math.Abs(point.Lon)<1e-6,"graph point uses terrain height and route position");using(var tiles=new TileStore(Path.Combine(root,"points"),null))using(var map=new MapCanvas(tiles)){bool changed=false;map.DocumentChanged+=delegate{changed=true;};map.AddProfilePoint(point);Check(!changed&&map.Document.Waypoints.Count==0&&map.TemporaryPoint.Elevation==100,"profile click creates temporary point without autosave");
var previous=map.TemporaryPoint;map.AddProfilePoint(new GeoPoint(48,37));Check(map.TemporaryPoint!=previous&&map.TemporaryPoint.Lat==48&&map.Document.Waypoints.Count==0,"next profile point replaces previous");
map.ShowTemporaryPoint(new GeoPoint(49,38),true,14);Check(map.TemporaryPoint.Lat==49&&Math.Abs(map.Center.Lat-49)<1e-6&&!changed,"coordinate search replaces temporary point and navigates without saving");
map.Selected=t;Check(map.TemporaryPoint==null,"switching object clears temporary point");
map.SetTemporaryRayAnchor(t.Points[0]);map.AddRayTemporaryPoint(t.Points[0],point);map.AddRayTemporaryPoint(t.Points[0],new GeoPoint(0,.005));Check(map.RayTemporaryPoints.Count==2,"ray retains multiple temporary marks");
var removeMark=map.RayTemporaryPoints[0];using(var menu=ProfilePointActions.CreateMenu(point,picked=>map.AddRayTemporaryPoint(t.Points[0],picked),picked=>{},()=>map.RemoveRayTemporaryPoint(removeMark))){menu.Items[1].PerformClick();Check(map.RayTemporaryPoints.Count==1&&!map.RayTemporaryPoints.Contains(removeMark),"context delete removes only targeted ray mark");menu.Items[0].PerformClick();Check(map.RayTemporaryPoints.Count==2,"context add creates ray mark");}
using(var menu=ProfilePointActions.CreateMenu(point,picked=>{},picked=>{}))Check(!menu.Items[1].Enabled,"context delete disabled when no mark is hit");map.Selected=null;Check(map.RayTemporaryPoints.Count==2,"unrelated selection does not clear ray marks");map.SetTemporaryRayAnchor(t.Points[0]);Check(map.RayTemporaryPoints.Count==2,"same ray anchor retains marks");map.SetTemporaryRayAnchor(t.Points[1]);Check(map.RayTemporaryPoints.Count==0,"new ray anchor clears marks");Check(!changed&&map.Document.Waypoints.Count==0,"ray marks never enter saved document");
using(var engine=new RayProfileEngine(Path.Combine(root,"ray-marks"))){engine.Step(t.Points[0],t.Points[1],new PointRadioOptions(),false,DateTime.UtcNow);for(int i=0;i<engine.Profile.Heights.Length;i++)engine.Profile.Heights[i]=150+20*Math.Sin(i*.2);var mark=engine.Profile.Points[engine.Profile.Points.Length/2];Check(RayProfilePainter.NearestTemporarySample(engine.Profile,mark)>=0,"ray mark maps to terrain sample");Check(RayProfilePainter.NearestTemporarySample(engine.Profile,new GeoPoint(20,20))<0,"off-ray marks are not projected onto unrelated terrain");using(var bitmap=RayProfilePainter.Render(engine,1100,650,"Временные метки",false,null,-1,new[]{mark}))bitmap.Save(Path.Combine(root,"ray-temporary-marks.png"));}
map.SaveProfilePoint(point);Check(changed&&map.Document.Waypoints.Count==1,"explicit save still creates persistent waypoint");}Check(ProfilePointActions.At(p,axes,new Point(0,0))==null,"outside plot cannot create point");string summary=RouteTerrain.Summary(p);Check(summary.Contains("20")&&summary.Contains("НЕПОЛНЫЕ"),"partial statistics explicit");using(var plot=new RoutePlot{Size=new Size(1100,650),Profile=p})using(var bitmap=new Bitmap(1100,650)){plot.DrawToBitmap(bitmap,plot.ClientRectangle);bitmap.Save(Path.Combine(root,"route-profile.png"));}using(var form=new RouteDetailsForm(t,root,false,()=>{},location=>{})){form.Show();Application.DoEvents();Check(form.Visible,"route info window opens offline");form.Close();}Console.WriteLine("ALL ROUTE TESTS PASSED");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
